import{_ as a,o,c as t,a0 as n}from"./chunks/framework.DYS8d9tm.js";const u=JSON.parse('{"title":"🏗️ System Infrastructure","description":"","frontmatter":{},"headers":[],"relativePath":"technical/infrastructure/index.md","filePath":"technical/infrastructure/index.md"}'),i={name:"technical/infrastructure/index.md"};function r(c,e,s,d,l,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="🏗️-system-infrastructure" tabindex="-1">🏗️ System Infrastructure <a class="header-anchor" href="#🏗️-system-infrastructure" aria-label="Permalink to &quot;🏗️ System Infrastructure&quot;">​</a></h1><p>The WealthFam ecosystem is supported by a set of robust orchestration and repair utilities designed to maintain system health and automate complex management tasks.</p><hr><h2 id="🛠️-management-orchestration" tabindex="-1">🛠️ Management &amp; Orchestration <a class="header-anchor" href="#🛠️-management-orchestration" aria-label="Permalink to &quot;🛠️ Management &amp; Orchestration&quot;">​</a></h2><h3 id="⚙️-system-orchestration" tabindex="-1">⚙️ <a href="https://github.com/WealthFam/Infra/tree/main/orchestration" target="_blank" rel="noreferrer">System Orchestration</a> <a class="header-anchor" href="#⚙️-system-orchestration" aria-label="Permalink to &quot;⚙️ [System Orchestration](https://github.com/WealthFam/Infra/tree/main/orchestration)&quot;">​</a></h3><p><code>Infra/orchestration/run_backend.py</code> manages the lifecycle of <code>Backend</code> (<code>:8000</code>), <code>Parser</code> (<code>:8001</code>), <code>Admin-Backend</code> (<code>:8002</code>), <code>Web-App</code> (<code>:5173</code>), and <code>Admin-Web</code> (<code>:5174</code>), initializing both <code>/data/logos</code> and <code>/data/vault</code> (or <code>&lt;workspace&gt;/data/{logos,vault}</code> locally) and running DuckDB recovery/vacuum before boot.</p><h3 id="🧹-database-maintenance-data-consistency-backups" tabindex="-1">🧹 Database Maintenance, <code>/data</code> Consistency &amp; Backups <a class="header-anchor" href="#🧹-database-maintenance-data-consistency-backups" aria-label="Permalink to &quot;🧹 Database Maintenance, `/data` Consistency &amp; Backups&quot;">​</a></h3><p>PostgreSQL vacuuming is handled natively by PostgreSQL. Embedded DuckDB files (<code>ingestion_engine_parser.duckdb</code> and <code>telemetry.duckdb</code>) use 4-slash absolute <code>duckdb:////data/...</code> URLs inside Linux Docker containers and are maintained by <code>Infra/scripts/maintenance/recover_db.py</code> (WAL recovery + <code>CHECKPOINT</code>) and <code>vacuum_db.py</code> (Parquet export/re-import compaction).</p><ul><li><strong><code>/data</code>-Aware Config Resolution</strong>: <code>Backend/app/core/config.py</code> and <code>Admin-Backend/app/core/config.py</code> automatically resolve <code>VAULT_STORAGE_PATH</code> and <code>LOGOS_STORAGE_PATH</code> to <code>/data/vault</code> and <code>/data/logos</code> in Linux containers (including normalizing relative <code>data/...</code> overrides under <code>/data</code>) and fall back to <code>&lt;workspace&gt;/data/...</code> locally. <code>Parser/config.py</code> guards its <code>duckdb:///data/</code> rewrite with <code>os.name != &quot;nt&quot;</code> to prevent local Windows runs from redirecting into <code>C:\\data</code>.</li></ul><h3 id="🌐-nginx-reverse-proxy-topology-infra-docker-nginx-conf" tabindex="-1">🌐 Nginx Reverse Proxy Topology (<code>Infra/docker/nginx.conf</code>) <a class="header-anchor" href="#🌐-nginx-reverse-proxy-topology-infra-docker-nginx-conf" aria-label="Permalink to &quot;🌐 Nginx Reverse Proxy Topology (`Infra/docker/nginx.conf`)&quot;">​</a></h3><ul><li><strong>Port 80 (Client Ingress)</strong>: Serves <code>Web-App</code> at <code>/</code> and proxies <code>/api</code> (<code>:8000</code>), <code>/ws/</code> (<code>:8000</code>), and write-only anonymous <code>/telemetry/</code> (<code>:8002/v1/telemetry/</code>). Consumer ingress has zero <code>/parser/</code> exposure; <code>Backend</code> communicates with <code>Parser</code> (<code>PARSER_SERVICE_URL</code>) and <code>Admin-Backend</code> (<code>ADMIN_SERVICE_URL</code>) internally.</li><li><strong>Port 8080 (Dedicated Admin Ingress)</strong>: Port-isolated server serving <code>Admin-Web</code> at <code>/</code> and proxying <code>/admin-api/</code> (including <code>WS /admin-api/logs/stream</code>) to <code>Admin-Backend</code> (<code>:8002/v1/</code>).</li></ul><h3 id="🩹-recovery-tools-startup-self-healing" tabindex="-1">🩹 Recovery Tools &amp; Startup Self-Healing <a class="header-anchor" href="#🩹-recovery-tools-startup-self-healing" aria-label="Permalink to &quot;🩹 Recovery Tools &amp; Startup Self-Healing&quot;">​</a></h3><ul><li><strong>Schema Migrations</strong>: Run programmatically on startup via Alembic, resolving and recovering schema state automatically.</li><li><strong>Vault Path Self-Healing</strong>: <code>Backend/app/main.py</code> executes <code>VaultService.heal_legacy_paths</code> non-blockingly on startup (complemented by runtime resolution in <code>VaultService.resolve_file_path</code>) to rewrite stale <code>/app/data/vault/...</code> and legacy <code>DocumentVault</code>/<code>DocumentVersion</code> paths only when the target file is verified on disk under <code>VAULT_STORAGE_PATH</code>.</li><li><strong>Zero-Config MultiFernet Key Rotation</strong>: <code>CryptoUtils</code> utilizes <code>cryptography.fernet.MultiFernet</code> with automatic fingerprint caching. New encryptions use <code>SECRET_KEY</code>, while decryptions check <code>SECRET_KEY</code>, any configured <code>PREVIOUS_SECRET_KEYS</code>, and automatically fall back to historical default keys (<code>CHANGE_THIS_TO_A_SECURE_SECRET_IN_PRODUCTION</code>, <code>CHANGE_THIS_IN_PROD</code>). Users transitioning from defaults to secure keys never face decryption failures or need to memorize default keys.</li><li><strong>Validation Log &amp; Error Hygiene</strong>: HTTP 422 error handlers in <code>Backend/app/main.py</code> strictly sanitize error output (<code>loc</code>, <code>msg</code>, <code>type</code>), preventing sensitive request payloads and credentials from appearing in logs or response bodies.</li><li><strong>Intuitive CORS Origin Normalization</strong>: Incoming <code>ALLOWED_ORIGINS</code> are cleaned of whitespace and trailing slashes (<code>/</code>), preventing subtle cross-origin blockages, and default safely to <code>*</code> (<code>allow_origin_regex=&quot;.*&quot;</code>) when omitted.</li></ul><hr><h2 id="🗺️-logical-layout" tabindex="-1">🗺️ Logical Layout <a class="header-anchor" href="#🗺️-logical-layout" aria-label="Permalink to &quot;🗺️ Logical Layout&quot;">​</a></h2><p>Infrastructure is decoupled from application logic to ensure that deployment environments can be swapped or hardened without affecting the core financial engine.</p><ul><li><strong>Environment Sync</strong>: Synchronized variable management across production/demo.</li><li><strong>Microservice Decoupling</strong>: Standalone service containers.</li><li><strong>Nginx Ingress</strong>: Centralized traffic management.</li></ul><h2 id="🛠️-deep-how-to-database-migration-recovery" tabindex="-1">🛠️ Deep How-To: Database Migration &amp; Recovery <a class="header-anchor" href="#🛠️-deep-how-to-database-migration-recovery" aria-label="Permalink to &quot;🛠️ Deep How-To: Database Migration &amp; Recovery&quot;">​</a></h2><h3 id="schema-migrations-alembic" tabindex="-1">Schema Migrations (Alembic) <a class="header-anchor" href="#schema-migrations-alembic" aria-label="Permalink to &quot;Schema Migrations (Alembic)&quot;">​</a></h3><p>Ecosystem schema changes are handled automatically via Alembic. If a migration is out of sync or needs to be forced manually:</p><ol><li>Connect to the backend terminal or container.</li><li>Run the manual migration command:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">alembic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> head</span></span></code></pre></div></li></ol><h3 id="how-to-perform-a-manual-postgresql-backup" tabindex="-1">How to Perform a Manual PostgreSQL Backup <a class="header-anchor" href="#how-to-perform-a-manual-postgresql-backup" aria-label="Permalink to &quot;How to Perform a Manual PostgreSQL Backup&quot;">​</a></h3><p>To prevent data loss, capture a raw snapshot of the ledger:</p><ol><li>Run the pg_dump utility:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wealthfam-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg_dump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wealthfam</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./backups/wealthfam_backup.sql</span></span></code></pre></div></li></ol><hr><div align="center"> *Hardened Infrastructure · Automated Maintenance · Reliable Operations* *Made with ❤️ by WGLabz* </div>',26)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
